-- Погрузка войск — тоже только из площадки сброса (23.10.2026).
--
-- Артём: стартовое задание «Погрузка» учило грузить бойцов откуда угодно (пачкой из окна флота —
-- load_to_ship не проверял, где корабль), а высаживать дальше можно только из площадки сброса.
-- Выравниваем правило: войска грузят и высаживают, только когда корабль целиком в площадке
-- (как уже было у load_unit_from_ground, unload_from_ship, unload_unit_at, unload_vehicle_at).
-- Ресурсы (снабжение, торговля) — без изменений.
-- Задания обучения «Погрузка» и «Десант» переписаны под это правило; в «Поселении» — нынешний зачёт условий (#84).
do $do$
declare d text; a text;
begin
  d := pg_get_functiondef('public.load_to_ship(uuid, text, integer)'::regprocedure);
  if position('is_in_orbital_drop' in d) > 0 then return; end if;
  a := $a$  if s.carrier_ship_id is not null then raise exception 'Корабль стоит в ангаре носителя'; end if;
$a$;
  if position(a in d) = 0 then raise exception 'load_to_ship: проверка носителя не найдена'; end if;
  d := replace(d, a, a || $a$  -- войска грузят только из площадки сброса — как и высаживают (sql/load_pad.sql)
  if (select is_in_orbital_drop(s.x, s.y, ship_box_w(t.width_cells, t.height_cells, s.facing), ship_box_h(t.width_cells, t.height_cells, s.facing))
        from ship_types t where t.id = s.ship_type) is null then
    raise exception 'Корабль должен целиком стоять в площадке сброса — на орбите коснись корабля, потом квадрата «ПЛОЩАДКА»';
  end if;
$a$);
  execute d;
end $do$;

update public.tutorial_steps set
  goal = 'Поставь корабль в площадку сброса и погрузи бойцов в трюм',
  hint = 'Орбита {capital_gen}: коснись корабля, потом квадрата «ПЛОЩАДКА» — он встанет в него сам. Затем Армия → твой командир → корабль → «Заполнить трюм» → «Погрузить»',
  mentor_republic = 'В зоне высадки {capital_gen} тебя ждут шестеро {troops}. Запомни главное правило десанта: грузить и высаживать войска можно, только когда корабль целиком стоит в площадке сброса — квадрате «ПЛОЩАДКА» на орбите. Коснись корабля, потом площадки: он сам встанет в неё. Потом открой «Армию» — корабль во флоте твоего командира — раскрой его и жми «Заполнить трюм». На борт берут тех, кто стоит в зоне высадки планеты.',
  mentor_cis = 'В зоне высадки {capital_gen} ожидают шесть {troops}. Основное правило десанта: погрузка и высадка войск выполняются только из площадки сброса — квадрата «ПЛОЩАДКА» на орбите. Выберите корабль и укажите площадку: он займёт её целиком. Затем раздел «Армия» → флот вашего командира → корабль → «Заполнить трюм». Погрузке подлежат подразделения из зоны высадки планеты.'
where id = 'cargo';

update public.tutorial_steps set
  hint = 'Коснись корабля, потом квадрата «ПЛОЩАДКА» — корабль встанет в него сам. Затем «Корабль» → «Трюм и ангар» → «Высадить» (или «Десант» на поверхности планеты)',
  mentor_republic = 'Мы на месте. Как и при погрузке, высаживать можно только из площадки сброса — квадрата «ПЛОЩАДКА» на орбите. Коснись корабля, потом площадки: он сам встанет в неё целиком. Потом открой трюм и жми «Высадить» — или спустись на поверхность и нажми «Десант»: карточку бойца тянут прямо на землю. На своей планете бойцы встают в зону высадки, на чужой — в полосу вторжения у нижнего края.',
  mentor_cis = 'Мы на месте. Как и погрузка, высадка возможна только из площадки сброса — квадрата «ПЛОЩАДКА» на орбите. Выберите корабль и укажите площадку: он займёт её целиком. Затем откройте трюм и отдайте приказ «Высадить» — либо на поверхности планеты команда «Десант»: карточку подразделения переносят на землю. На своей планете — в зону высадки, на чужой — в полосу вторжения у нижнего края.'
where id = 'drop';

update public.tutorial_steps set
  mentor_republic = 'В центре каждой планеты — поселение, твой главный доход. Раз в сутки оно платит кредиты: чем выше довольство, тем больше — от 300 до 1300. Каждые сутки жители выдвигают условия: охрана, пожертвование, праздник, патруль техники, прикрытие с орбиты, мародёр. Каждое выполненное — довольство +5, проваленное — −4, а выполнил все — ещё +5. Что осталось на сегодня, видно в карточке планеты. На сотне жители шлют подарки. И помни: кто держит поселение, тот держит планету.',
  mentor_cis = 'В центре планеты расположено поселение — основной источник дохода. Выплата раз в сутки: от 300 до 1300 кредитов в зависимости от довольства. Ежесуточно поселение выдвигает условия: охрана, пожертвование, праздник, патруль техники, орбитальное прикрытие, устранение мародёра. Каждое выполненное — довольство +5, проваленное — минус 4, все выполненные — ещё +5. Остаток условий на сутки указан в карточке планеты. При максимальном довольстве возможны подарки. Контроль над поселением означает контроль над планетой.'
where id = 'settlement';
